∀ (a b : Nat),
  instLTNat.lt a b →
    have I := Finset.Icc a b;
    have L := Finset.Icc a (instHSub.hSub b 1);
    have R := Finset.Icc (instHAdd.hAdd a 1) b;
    have pairs := fun S => Finset.filter (fun z => instLENat.le z.fst z.snd) (S.product S);
    And (Eq (Finset.instUnion.union (pairs L) (pairs R)) ((pairs I).erase { fst := a, snd := b }))
      (Eq
        (instHAdd.hAdd
          (instHAdd.hAdd (pairs L).card (Finset.instUnion.union (pairs L) (pairs R)).card) 1)
        (instHPow.hPow I.card 2))

∀ (a b : Nat),
  have I := Finset.Icc a b;
  have pairs := Finset.filter (fun z => instLENat.le z.fst z.snd) (I.product I);
  have rows := (Finset.instSingleton.singleton a).product pairs;
  have columns := Finset.image (fun z => { fst := z.fst, snd := { fst := z.snd, snd := b } }) pairs;
  Eq (Finset.instUnion.union rows columns).card (instHPow.hPow I.card 2)
